"""Exact FP producer/29-role authority consumers; no runtime or generic PASS shortcut."""
from pathlib import Path
import hashlib

def need(ok,why):
 if not ok:raise RuntimeError(why)
def digest(b):return hashlib.sha256(b).hexdigest()
def authority_pairs(pairs,roles):
 need(isinstance(pairs,list) and len(pairs)==29,'exact29 retained authority pairs required')
 expected={(v['original'],v['retained']) for v in roles.values()};actual=[]
 for pair in pairs:
  need(isinstance(pair,dict) and set(pair)=={'original','retained','outside_generic_receipt_inventory'} and pair['outside_generic_receipt_inventory'] is True,'exact retained producer pair shape required')
  for key in ('original','retained'):
   row=pair[key];need(isinstance(row,dict) and set(row)=={'path','device','inode','mode','uid','gid','size','nlink','sha256','mtime_ns','ctime_ns'},'actual11-field retained producer row required')
  a,b=pair['original'],pair['retained'];actual.append((a['path'],b['path']));need(a['sha256']==b['sha256'] and a['size']==b['size'] and (a['device'],a['inode'])!=(b['device'],b['inode']) and a['nlink']==b['nlink']==1,'retained original byte/independence join differs')
 need(len(set(actual))==29 and set(actual)==expected,'exact29 unique role/path set required')
 return {kind:next(p for p in pairs if p['original']['path']==v['original'] and p['retained']['path']==v['retained']) for kind,v in roles.items()}
def typed_source(request,obs,selected,expected,read):
 need(isinstance(expected,dict),'PENDING_REAL_FP_TYPED_SOURCE_PINS')
 need(request.get('source_identity',{}).get('inode')==expected['source_inode'] and obs['candidate_root'].get('inode')==expected['source_inode'],'FP typed source inode differs')
 need(request.get('source_derivative_sha256')==expected['source_derivative_sha256'] and request.get('materialization_sha256')==expected['materialization_sha256'] and request.get('candidate_identity_scope')=='base_git_commit_only','FP typed source derivative differs')
 for key,hashkey in [('manifest_path','manifest_sha256'),('receipt_path','receipt_sha256')]:
  p=expected[key];need(selected.get(p,{}).get('sha256')==expected[hashkey] and digest(read(p))==expected[hashkey],'FP typed source receipt differs')
 receipt=__import__('json').loads(read(expected['receipt_path']));need(receipt.get('status')=='PASS_SOURCE_MATERIALIZATION_ONLY' and receipt.get('source')==request['source_root'] and receipt.get('source_derivative_sha256')==expected['source_derivative_sha256'] and receipt.get('materialization_sha256')==expected['materialization_sha256'],'FP typed materialization differs')
 need(digest(read(str(Path(request['source_root'])/'arch/x86_64/kernel/cpu.c')))==expected['cpu_source_sha256'],'FP source CPU hash differs')
 return True
def production(proof,byrole,read,expected,header_sha):
 need(isinstance(expected,dict),'PENDING_REAL_FP_PRODUCTION_SOURCE_PINS')
 need(isinstance(proof,dict) and proof.get('status')=='PASS' and proof.get('default_link')=='PENDING_IMAGE_MAKE' and proof.get('descriptor_relocations_and_release_body')=='PENDING_POSTBUILD','exact FP prebuild producer required; not linked acceptance')
 rows=proof.get('checks');need(isinstance(rows,list) and len(rows)==8,'exact four full plus four export checks required')
 names=['release-full-cpu-selected','release-full-cpu-fallback','release-full-crate-native','release-full-crate-legacy']
 exports={'selected-cpu.o':'release-selected-cpu.o','fallback-cpu.o':'release-fallback-cpu.o','native-mckernel_rust.o':'release-native-mckernel_rust.o','legacy-mckernel_rust.o':'release-legacy-mckernel_rust.o'}
 need([r.get('phase') for r in rows]==names+['release-export-'+n for n in exports],'FP production check phases/order differ')
 header=read('release-production-c-abi-assertions.h');need(digest(header)==header_sha,'FP ABI header bytes/assertions differ')
 for row in rows[:4]:
  need(row.get('exit_code')==0 and isinstance(row.get('argv'),list) and row['argv'] and isinstance(row.get('cwd'),str),'FP full production command failed/missing')
  need(row.get('cpu_source_sha256')==expected['cpu_source_sha256'] and row.get('assertion_header_sha256')==header_sha and row.get('generated_rust_make_sha256')==byrole['build.make']['original']['sha256'],'FP full production source/header/make binding differs')
  if row['phase'].startswith('release-full-cpu-'):
   need(row['argv'].count('-DMCKERNEL_RUST_X86_CPU_HELPERS')==(1 if row['phase'].endswith('selected') else 0) and '-include' in row['argv'],'FP selected/fallback full TU flags differ')
  else:need(row['argv'].count('native_linux_irq_work_v6_12')==(1 if row['phase'].endswith('native') else 0) and '/nightly/bin/rustc' in row['argv'],'FP full crate native/legacy cfg differs')
 for row,(name,role) in zip(rows[4:],exports.items()):
  obj=byrole[role]['original'];nm=read(role+'.nm');err=read(role+'.nm.stderr');symbols=[line.split() for line in nm.decode().splitlines()]
  need(row.get('exit_code')==0 and row.get('object_sha256')==obj['sha256'] and row.get('stdout_sha256')==digest(nm) and row.get('stderr_bytes')==len(err)==0 and len(nm)<1048576,'FP export actual role/stream hashes differ')
  need(isinstance(row.get('argv'),list) and row['argv'][-3:]==['-S','--defined-only',str(Path(expected['container_build_root'])/Path(obj['path']).relative_to(expected['build_root']))],'FP export argv/object role differs')
  definitions=[v for v in symbols if len(v)>=4 and v[-1]=='release_fp_regs' and v[-2]=='T'];need(len(definitions)==(0 if name=='selected-cpu.o' else 1),'FP release export ownership differs')
  if 'mckernel_rust' in name:
   descriptors=[v for v in symbols if len(v)>=4 and 'RELEASE_FP_REGS_DEBUG' in v[-1]];need(len(descriptors)==1 and int(descriptors[0][-3],16)==32,'FP descriptor size/export differs')
 return True
def postbuild(actual,expected,byrole):
 need(isinstance(expected,dict),'PENDING_REAL_FP_POSTBUILD_LINK_BODY_RELOCATION_AUTHORITY')
 need(isinstance(actual,dict) and actual==expected,'exact independently pinned FP postbuild facts differ')
 need(set(actual)=={'default_consumer','release_body','descriptor'},'complete FP postbuild fact groups required')
 d=actual['default_consumer'];b=actual['release_body'];r=actual['descriptor']
 for key,role in [('cpu_object_sha256','cpu.c.o'),('rust_object_sha256','mckernel_rust.o'),('image_sha256','mckernel.img')]:need(d.get(key)==byrole[role]['original']['sha256'],'FP linked consumer artifact differs')
 need(d.get('link_command_sha256')==byrole['link.txt']['original']['sha256'] and [d.get(k) for k in ('selected_cpu_release_definitions','linked_image_release_definitions','linked_rust_release_definitions')]==[0,1,1],'FP default link ownership facts differ')
 need(d.get('process_object_sha256')==byrole['process.c.o']['original']['sha256'] and isinstance(d.get('process_release_relocations'),list) and d['process_release_relocations'] and all(isinstance(x,dict) and x.get('symbol')=='release_fp_regs' and type(x.get('offset')) is int and x['offset']>=0 and isinstance(x.get('type'),str) and x['type'] for x in d['process_release_relocations']),'FP real process consumer relocation facts required')
 need(b.get('rust_object_sha256')==byrole['mckernel_rust.o']['original']['sha256'] and [b.get(k) for k in ('fp_regs_offset','pointer_bytes','free_flags')]==[4784,8,0] and b.get('page_count_expression')=='wrapping_ulong_xsave_size_plus4095_shift12_to_cint' and b.get('null_store_after_free') is True and b.get('scalar_only') is True,'FP linked release body facts differ')
 need(r.get('rust_object_sha256')==byrole['mckernel_rust.o']['original']['sha256'] and r.get('descriptor_size')==32 and r.get('descriptor_alignment')==8 and r.get('descriptor_field_relocations')==[0,8] and r.get('fmt_pointer')==0 and r.get('line_flags_offset')==24 and r.get('initial_debug_flags')==0 and r.get('free_target_symbol')=='_ihk_mc_free_pages' and r.get('function_string')=='release_fp_regs','FP descriptor relocation facts differ')
 return True

